import { Helmet } from "react-helmet-async";

export type SchemaType = "LocalBusiness" | "Service" | "BreadcrumbList" | "Article";

interface SchemaMarkupProps {
    type: SchemaType;
    data: Record<string, any>;
}

export const SchemaMarkup = ({ type, data }: SchemaMarkupProps) => {
    return (
        <Helmet>
            <script type="application/ld+json">
                {JSON.stringify({
                    "@context": "https://schema.org",
                    "@type": type,
                    ...data,
                })}
            </script>
        </Helmet>
    );
};

import { useState, useEffect, useRef, useCallback } from "react";
import { Upload, Loader2, Image as ImageIcon, Search, Check } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
} from "@/components/ui/dialog";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select";
import { useToast } from "@/hooks/use-toast";
import { supabase } from "@/integrations/supabase/client";

interface MediaFile {
    id: string;
    name: string;
    url: string;
    folder: string;
}

interface MediaPickerModalProps {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    onSelect: (url: string) => void;
}

const FOLDERS = ["portfolio", "services", "blogs", "general"];
const BUCKET_NAME = "media";

const MediaPickerModal = ({ open, onOpenChange, onSelect }: MediaPickerModalProps) => {
    const [files, setFiles] = useState<MediaFile[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [isUploading, setIsUploading] = useState(false);
    const [selectedFolder, setSelectedFolder] = useState<string>("all");
    const [searchQuery, setSearchQuery] = useState("");
    const [selectedUrl, setSelectedUrl] = useState<string | null>(null);
    const fileInputRef = useRef<HTMLInputElement>(null);
    const { toast } = useToast();

    useEffect(() => {
        if (open) {
            fetchFiles();
        }
    }, [open]);

    const fetchFiles = async () => {
        setIsLoading(true);
        const allFiles: MediaFile[] = [];

        for (const folder of FOLDERS) {
            const { data, error } = await supabase.storage
                .from(BUCKET_NAME)
                .list(folder, { limit: 100, sortBy: { column: "created_at", order: "desc" } });

            if (data && !error) {
                const folderFiles = data
                    .filter((file) => file.name !== ".emptyFolderPlaceholder")
                    .map((file) => {
                        const { data: { publicUrl } } = supabase.storage
                            .from(BUCKET_NAME)
                            .getPublicUrl(`${folder}/${file.name}`);
                        return {
                            id: file.id || `${folder}-${file.name}`,
                            name: file.name,
                            url: publicUrl,
                            folder,
                        };
                    });
                allFiles.push(...folderFiles);
            }
        }

        setFiles(allFiles);
        setIsLoading(false);
    };

    const handleUpload = async (uploadFiles: FileList | null) => {
        if (!uploadFiles || uploadFiles.length === 0) return;

        setIsUploading(true);
        const folder = selectedFolder === "all" ? "general" : selectedFolder;

        try {
            const file = uploadFiles[0];
            const fileExt = file.name.split(".").pop();
            const fileName = `${Date.now()}-${Math.random().toString(36).substring(2, 8)}.${fileExt}`;
            const filePath = `${folder}/${fileName}`;

            const { error } = await supabase.storage
                .from(BUCKET_NAME)
                .upload(filePath, file);

            if (error) throw error;

            const { data: { publicUrl } } = supabase.storage
                .from(BUCKET_NAME)
                .getPublicUrl(filePath);

            toast({ title: "Upload successful" });
            onSelect(publicUrl);
            onOpenChange(false);
        } catch (error: any) {
            toast({
                title: "Upload failed",
                description: error.message,
                variant: "destructive",
            });
        } finally {
            setIsUploading(false);
        }
    };

    const handleSelect = (url: string) => {
        setSelectedUrl(url);
    };

    const handleConfirmSelection = () => {
        if (selectedUrl) {
            onSelect(selectedUrl);
            onOpenChange(false);
            setSelectedUrl(null);
        }
    };

    const filteredFiles = files.filter((file) => {
        const matchesFolder = selectedFolder === "all" || file.folder === selectedFolder;
        const matchesSearch = file.name.toLowerCase().includes(searchQuery.toLowerCase());
        return matchesFolder && matchesSearch;
    });

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent className="max-w-4xl max-h-[85vh] flex flex-col">
                <DialogHeader>
                    <DialogTitle>Select Image</DialogTitle>
                </DialogHeader>

                {/* Toolbar */}
                <div className="flex flex-wrap items-center gap-3 py-2">
                    <div className="relative flex-1 min-w-[180px]">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                        <Input
                            placeholder="Search..."
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                            className="pl-10 h-9"
                        />
                    </div>
                    <Select value={selectedFolder} onValueChange={setSelectedFolder}>
                        <SelectTrigger className="w-[130px] h-9">
                            <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                            <SelectItem value="all">All Folders</SelectItem>
                            {FOLDERS.map((folder) => (
                                <SelectItem key={folder} value={folder} className="capitalize">
                                    {folder}
                                </SelectItem>
                            ))}
                        </SelectContent>
                    </Select>
                    <input
                        type="file"
                        ref={fileInputRef}
                        onChange={(e) => handleUpload(e.target.files)}
                        accept="image/*"
                        className="hidden"
                    />
                    <Button size="sm" variant="outline" onClick={() => fileInputRef.current?.click()} disabled={isUploading}>
                        {isUploading ? <Loader2 className="w-4 h-4 animate-spin" /> : <Upload className="w-4 h-4 mr-1" />}
                        Upload
                    </Button>
                </div>

                {/* Files Grid */}
                <div className="flex-1 overflow-y-auto min-h-0">
                    {isLoading ? (
                        <div className="flex items-center justify-center h-40">
                            <Loader2 className="w-6 h-6 animate-spin text-primary" />
                        </div>
                    ) : filteredFiles.length === 0 ? (
                        <div className="text-center py-12 text-muted-foreground">
                            <ImageIcon className="w-12 h-12 mx-auto mb-2 opacity-30" />
                            <p>No images found</p>
                        </div>
                    ) : (
                        <div className="grid grid-cols-3 sm:grid-cols-4 md:grid-cols-5 gap-3 p-1">
                            {filteredFiles.map((file) => (
                                <button
                                    key={file.id}
                                    onClick={() => handleSelect(file.url)}
                                    className={`aspect-square relative rounded-lg overflow-hidden border-2 transition-all ${selectedUrl === file.url
                                            ? "border-primary ring-2 ring-primary/30"
                                            : "border-transparent hover:border-primary/50"
                                        }`}
                                >
                                    <img
                                        src={file.url}
                                        alt={file.name}
                                        className="w-full h-full object-cover"
                                        loading="lazy"
                                    />
                                    {selectedUrl === file.url && (
                                        <div className="absolute inset-0 bg-primary/20 flex items-center justify-center">
                                            <Check className="w-8 h-8 text-primary bg-background rounded-full p-1" />
                                        </div>
                                    )}
                                </button>
                            ))}
                        </div>
                    )}
                </div>

                {/* Footer */}
                <div className="flex justify-end gap-2 pt-4 border-t">
                    <Button variant="outline" onClick={() => onOpenChange(false)}>
                        Cancel
                    </Button>
                    <Button variant="gold" onClick={handleConfirmSelection} disabled={!selectedUrl}>
                        Select Image
                    </Button>
                </div>
            </DialogContent>
        </Dialog>
    );
};

export default MediaPickerModal;

import { useNavigate } from "react-router-dom";
import { Plus, UserPlus, FileText, Image as ImageIcon, ArrowRight } from "lucide-react";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

export function QuickActionButton({
    icon: Icon,
    label,
    href,
    gradient,
    onClick
}: {
    icon: any;
    label: string;
    href?: string;
    gradient: string;
    onClick?: () => void;
}) {
    const navigate = useNavigate();

    const handleClick = () => {
        if (onClick) onClick();
        if (href) navigate(href);
    };

    return (
        <button
            onClick={handleClick}
            className="group relative overflow-hidden rounded-xl border border-[hsl(var(--admin-border))] bg-[hsl(var(--admin-card))] p-5 hover:shadow-md transition-all duration-300 w-full"
        >
            {/* Background gradient on hover */}
            <div className={cn(
                "absolute inset-0 opacity-0 group-hover:opacity-100 transition-opacity duration-300 bg-gradient-to-br",
                gradient
            )} />

            <div className="relative flex items-center justify-between">
                <div className="flex items-center gap-3">
                    <div className={cn(
                        "p-2.5 rounded-lg bg-gradient-to-br shadow-sm",
                        gradient
                    )}>
                        <Icon className="h-5 w-5 text-white" />
                    </div>
                    <span className="text-sm font-semibold text-[hsl(var(--admin-foreground))]">{label}</span>
                </div>
                <ArrowRight className="h-4 w-4 text-[hsl(var(--admin-muted))] opacity-0 group-hover:opacity-100 transition-opacity" />
            </div>
        </button>
    );
}

export function QuickActions() {
    const actions = [
        { label: "New Project", icon: Plus, gradient: "from-blue-500 to-blue-600", path: "/admin/portfolio" },
        { label: "Add Lead", icon: UserPlus, gradient: "from-green-500 to-green-600", path: "/admin/leads" },
        { label: "New Testimonial", icon: FileText, gradient: "from-purple-500 to-purple-600", path: "/admin/testimonials" },
        { label: "Upload Media", icon: ImageIcon, gradient: "from-orange-500 to-orange-600", path: "/admin/media" },
    ];

    return (
        <div className="rounded-xl border border-[hsl(var(--admin-border))] bg-[hsl(var(--admin-card))] p-6 shadow-sm">
            <h3 className="mb-5 text-lg font-semibold text-[hsl(var(--admin-foreground))]">Quick Actions</h3>
            <div className="grid grid-cols-1 gap-3">
                {actions.map((action) => (
                    <QuickActionButton
                        key={action.label}
                        icon={action.icon}
                        label={action.label}
                        href={action.path}
                        gradient={action.gradient}
                    />
                ))}
            </div>
        </div>
    );
}

import { useQuery } from "@tanstack/react-query";
import { formatDistanceToNow } from "date-fns";
import {
    Activity,
    UserPlus,
    FileEdit,
    Briefcase,
    MessageSquare,
    Shield
} from "lucide-react";
import { supabase } from "@/integrations/supabase/client";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Skeleton } from "@/components/ui/skeleton";
import { DateRange } from "react-day-picker";

interface ActivityItem {
    id: string;
    action: string;
    entity_type: string;
    created_at: string;
    user_id?: string;
    details?: {
        invited_by?: string;
        email?: string;
        role?: string;
        [key: string]: any;
    };
}

export function RecentActivityFeed({ dateRange }: { dateRange?: DateRange }) {
    const { data: activities, isLoading } = useQuery({
        queryKey: ["recent-activity", dateRange],
        queryFn: async () => {
            let query = supabase
                .from("audit_logs")
                .select("*")
                .order("created_at", { ascending: false })
                .limit(20); // increased limit to ensure we see enough if filtered

            // Filtering logic
            if (dateRange?.from) {
                // Use ISO string, but careful with timestamp logic.
                // We want end of day for 'to'? or just raw date?
                // Usually dateRange from day picker is start of day.
                // If 'to' is undefined, it means single day selection.
                query = query.gte("created_at", dateRange.from.toISOString());
            }

            if (dateRange?.to) {
                // Set to end of day for 'to' date
                const toDate = new Date(dateRange.to);
                toDate.setHours(23, 59, 59, 999);
                query = query.lte("created_at", toDate.toISOString());
            } else if (dateRange?.from) {
                // If only 'from' is selected, assume it's a single day or range start?
                // Usually range picker handles 'to' as undefined while selecting.
                // Let's just filter by 'from' start if 'to' is missing, effectively >= from.
            }

            const { data, error } = await query;

            if (error) throw error;
            return data as unknown as ActivityItem[];
        },
        refetchInterval: 30000,
    });

    if (isLoading) {
        return (
            <div className="space-y-4">
                {[1, 2, 3].map((i) => (
                    <div key={i} className="flex items-center gap-4">
                        <Skeleton className="h-10 w-10 rounded-full" />
                        <div className="space-y-2 flex-1">
                            <Skeleton className="h-4 w-[200px]" />
                            <Skeleton className="h-3 w-[150px]" />
                        </div>
                    </div>
                ))}
            </div>
        );
    }

    if (!activities?.length) {
        return (
            <div className="flex flex-col items-center justify-center py-8 text-center text-muted-foreground">
                <Activity className="h-8 w-8 mb-2 opacity-50" />
                <p>No recent activity in selected period.</p>
            </div>
        );
    }

    const getIcon = (item: ActivityItem) => {
        // Handle specific actions first
        if (item.action === "USER_INVITED") return <UserPlus className="h-4 w-4" />;

        // Handle by entity type
        const type = item.entity_type?.toLowerCase();
        if (type?.includes("blog")) return <FileEdit className="h-4 w-4" />;
        if (type?.includes("project") || type?.includes("portfolio")) return <Briefcase className="h-4 w-4" />;
        if (type?.includes("lead")) return <MessageSquare className="h-4 w-4" />;
        if (type?.includes("user")) return <UserPlus className="h-4 w-4" />;

        return <Shield className="h-4 w-4" />;
    };

    const getBadges = (action: string) => {
        const act = action.toLowerCase();
        if (act.includes("create") || act.includes("invited")) return "bg-admin-success/10 text-admin-success border-admin-success/20";
        if (act.includes("update")) return "bg-admin-info/10 text-admin-info border-admin-info/20";
        if (act.includes("delete")) return "bg-admin-danger/10 text-admin-danger border-admin-danger/20";
        return "bg-admin-surface text-admin-muted border-admin-border";
    };

    const formatActionLabel = (item: ActivityItem) => {
        if (item.action === "USER_INVITED") return "User Invited";
        const entity = item.entity_type?.replace(/s$/, "") || "Item";
        const action = item.action || "Modified";
        return `${entity.charAt(0).toUpperCase() + entity.slice(1)} ${action.charAt(0).toUpperCase() + action.slice(1)}`;
    };

    const getUserLabel = (item: ActivityItem) => {
        if (item.details?.invited_by) return "Admin";
        if (item.user_id) return "User";
        return "System";
    };

    return (
        <ScrollArea className="h-[400px] pr-4">
            <div className="space-y-3">
                {activities.map((activity) => (
                    <div key={activity.id} className="flex gap-4 group items-start border-b border-admin-border/50 pb-4 last:border-0 hover:bg-admin-surface/30 p-2 rounded-lg transition-colors">
                        <div className={`mt-0.5 flex h-8 w-8 shrink-0 items-center justify-center rounded-lg border ${getBadges(activity.action)}`}>
                            {getIcon(activity)}
                        </div>
                        <div className="flex flex-col gap-1 min-w-0 flex-1">
                            <div className="flex items-center justify-between">
                                <span className="text-sm font-medium leading-none text-admin-foreground">
                                    {formatActionLabel(activity)}
                                </span>
                                <span className="text-[10px] text-admin-muted tabular-nums">
                                    {formatDistanceToNow(new Date(activity.created_at), { addSuffix: true })}
                                </span>
                            </div>

                            <div className="text-xs text-admin-muted flex gap-2 items-center mt-1">
                                <span className={`px-1.5 py-0.5 rounded text-[10px] border ${getBadges(activity.action)}`}>
                                    {activity.action.toUpperCase()}
                                </span>
                                <span>
                                    • by <span className="text-admin-gold">{getUserLabel(activity)}</span>
                                </span>
                            </div>

                            {activity.details && typeof activity.details === 'object' && Object.keys(activity.details).length > 0 && (
                                <div className="mt-1.5 text-xs bg-admin-surface p-2 rounded border border-admin-border font-mono truncate max-w-[300px] text-admin-muted/80">
                                    {activity.action === "USER_INVITED" ? (
                                        `Invited: ${activity.details.email} as ${activity.details.role}`
                                    ) : (
                                        JSON.stringify(activity.details).slice(0, 60) + (JSON.stringify(activity.details).length > 60 ? "..." : "")
                                    )}
                                </div>
                            )}
                        </div>
                    </div>
                ))}
            </div>
        </ScrollArea>
    );
}

import { useState } from "react";
import {
    Sheet,
    SheetContent,
    SheetHeader,
    SheetTitle,
    SheetDescription,
} from "@/components/ui/sheet";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Textarea } from "@/components/ui/textarea";
import { Separator } from "@/components/ui/separator";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select";
import {
    MapPin,
    Home,
    Ruler,
    IndianRupee,
    Flame,
    Thermometer,
    Snowflake,
    Calendar,
    Phone,
    Mail,
    Save,
    Trash2,
} from "lucide-react";

interface EstimateLead {
    id: string;
    created_at: string;
    name: string;
    email: string | null;
    phone: string | null;
    property_type: string | null;
    city: string | null;
    city_tier: string | null;
    state: string | null;
    area: number;
    budget: number;
    scopes: string[];
    design_package: string | null;
    timeline: string | null;
    site_visits: number;
    estimate_total_min: number;
    estimate_total_max: number;
    estimate_breakdown: Record<string, any>;
    lead_score: number;
    lead_category: "HOT" | "WARM" | "COLD";
    status: "new" | "contacted" | "converted" | "archived";
    notes: string | null;
    admin_notes: string | null;
}

interface EstimateLeadDetailSheetProps {
    lead: EstimateLead | null;
    open: boolean;
    onOpenChange: (open: boolean) => void;
    onSave: (updates: Partial<EstimateLead> & { id: string }) => void;
    onDelete: (id: string) => void;
}

const categoryConfig = {
    HOT: { icon: Flame, color: "text-red-500", bg: "bg-red-500/10", border: "border-red-500/30" },
    WARM: { icon: Thermometer, color: "text-amber-500", bg: "bg-amber-500/10", border: "border-amber-500/30" },
    COLD: { icon: Snowflake, color: "text-blue-500", bg: "bg-blue-500/10", border: "border-blue-500/30" },
};

const formatCurrency = (val: number) =>
    new Intl.NumberFormat("en-IN", { style: "currency", currency: "INR", maximumFractionDigits: 0 }).format(val);

export function EstimateLeadDetailSheet({
    lead,
    open,
    onOpenChange,
    onSave,
    onDelete,
}: EstimateLeadDetailSheetProps) {
    const [status, setStatus] = useState(lead?.status || "new");
    const [adminNotes, setAdminNotes] = useState(lead?.admin_notes || "");

    // Sync state when lead changes
    if (lead && (status !== lead.status || adminNotes !== (lead.admin_notes || ""))) {
        if (status !== lead.status) setStatus(lead.status);
        if (adminNotes !== (lead.admin_notes || "")) setAdminNotes(lead.admin_notes || "");
    }

    if (!lead) return null;

    const cat = categoryConfig[lead.lead_category];
    const CatIcon = cat.icon;
    const breakdown = lead.estimate_breakdown || {};

    return (
        <Sheet open={open} onOpenChange={onOpenChange}>
            <SheetContent className="w-full sm:max-w-xl overflow-y-auto">
                <SheetHeader className="pb-4">
                    <SheetTitle className="flex items-center gap-3">
                        <span>{lead.name}</span>
                        <Badge variant="outline" className={`${cat.bg} ${cat.color} ${cat.border}`}>
                            <CatIcon className="w-3 h-3 mr-1" />
                            {lead.lead_category}
                        </Badge>
                    </SheetTitle>
                    <SheetDescription>
                        Submitted {new Date(lead.created_at).toLocaleDateString("en-IN", { day: "numeric", month: "short", year: "numeric" })}
                    </SheetDescription>
                </SheetHeader>

                {/* Contact Info */}
                <div className="space-y-6 mt-2">
                    <div className="grid grid-cols-2 gap-3">
                        {lead.email && (
                            <div className="flex items-center gap-2 text-sm">
                                <Mail className="w-4 h-4 text-muted-foreground" />
                                <a href={`mailto:${lead.email}`} className="text-primary hover:underline">{lead.email}</a>
                            </div>
                        )}
                        {lead.phone && (
                            <div className="flex items-center gap-2 text-sm">
                                <Phone className="w-4 h-4 text-muted-foreground" />
                                <a href={`tel:${lead.phone}`} className="text-primary hover:underline">{lead.phone}</a>
                            </div>
                        )}
                    </div>

                    <Separator />

                    {/* Property Details */}
                    <div>
                        <h4 className="text-sm font-semibold mb-3">Property Details</h4>
                        <div className="grid grid-cols-2 gap-3">
                            <div className="flex items-center gap-2 text-sm rounded-lg border p-3">
                                <Home className="w-4 h-4 text-muted-foreground shrink-0" />
                                <div>
                                    <p className="text-xs text-muted-foreground">Type</p>
                                    <p className="font-medium">{lead.property_type || "—"}</p>
                                </div>
                            </div>
                            <div className="flex items-center gap-2 text-sm rounded-lg border p-3">
                                <MapPin className="w-4 h-4 text-muted-foreground shrink-0" />
                                <div>
                                    <p className="text-xs text-muted-foreground">Location</p>
                                    <p className="font-medium">{lead.city || "—"}{lead.city_tier ? ` (${lead.city_tier})` : ""}</p>
                                </div>
                            </div>
                            <div className="flex items-center gap-2 text-sm rounded-lg border p-3">
                                <Ruler className="w-4 h-4 text-muted-foreground shrink-0" />
                                <div>
                                    <p className="text-xs text-muted-foreground">Area</p>
                                    <p className="font-medium">{lead.area.toLocaleString()} sq ft</p>
                                </div>
                            </div>
                            <div className="flex items-center gap-2 text-sm rounded-lg border p-3">
                                <IndianRupee className="w-4 h-4 text-muted-foreground shrink-0" />
                                <div>
                                    <p className="text-xs text-muted-foreground">Budget</p>
                                    <p className="font-medium">{formatCurrency(lead.budget)}</p>
                                </div>
                            </div>
                        </div>
                    </div>

                    <Separator />

                    {/* Scope & Design */}
                    <div>
                        <h4 className="text-sm font-semibold mb-3">Selections</h4>
                        <div className="space-y-2">
                            <div className="flex flex-wrap gap-2">
                                {(lead.scopes || []).map((scope: string) => (
                                    <Badge key={scope} variant="secondary">{scope}</Badge>
                                ))}
                            </div>
                            <div className="grid grid-cols-3 gap-3 text-sm">
                                <div className="rounded-lg border p-3">
                                    <p className="text-xs text-muted-foreground">Design Package</p>
                                    <p className="font-medium capitalize">{lead.design_package?.replace(/_/g, " ") || "—"}</p>
                                </div>
                                <div className="rounded-lg border p-3">
                                    <p className="text-xs text-muted-foreground">Timeline</p>
                                    <p className="font-medium">{lead.timeline || "—"}</p>
                                </div>
                                <div className="rounded-lg border p-3">
                                    <p className="text-xs text-muted-foreground">Site Visits</p>
                                    <p className="font-medium">{lead.site_visits}</p>
                                </div>
                            </div>
