import { useState } from "react";
import {
    DndContext,
    closestCorners,
    KeyboardSensor,
    PointerSensor,
    useSensor,
    useSensors,
    DragOverlay,
    defaultDropAnimationSideEffects,
    DragEndEvent,
    DragStartEvent,
    DragOverEvent,
    DropAnimation,
} from "@dnd-kit/core";
import {
    arrayMove,
    SortableContext,
    sortableKeyboardCoordinates,
    verticalListSortingStrategy,
} from "@dnd-kit/sortable";
import { LeadCard } from "./LeadCard";
import { leadStatusOptions } from "@/lib/validations";
import { useDroppable } from "@dnd-kit/core";
import { cn } from "@/lib/utils";

interface Lead {
    id: string;
    name: string;
    email?: string;
    phone?: string;
    service?: string;
    status: string;
    notes?: string;
    created_at?: string;
    score?: number;
}

interface LeadPipelineProps {
    leads: Lead[];
    onLeadMove: (leadId: string, newStatus: string) => void;
    onLeadClick: (lead: Lead) => void;
}

const statusColors: Record<string, string> = {
    "new": "bg-blue-100 text-blue-700 border-blue-200",
    "contacted": "bg-purple-100 text-purple-700 border-purple-200",
    "qualified": "bg-cyan-100 text-cyan-700 border-cyan-200",
    "proposal": "bg-orange-100 text-orange-700 border-orange-200",
    "negotiation": "bg-yellow-100 text-yellow-700 border-yellow-200",
    "closed": "bg-green-100 text-green-700 border-green-200",
    "lost": "bg-red-100 text-red-700 border-red-200",
};

const Column = ({ id, leads, onLeadClick }: { id: string; leads: Lead[]; onLeadClick: (l: Lead) => void }) => {
    const { setNodeRef, isOver } = useDroppable({ id });
    const colorClass = statusColors[id as keyof typeof statusColors] || "bg-gray-100 text-gray-700 border-gray-200";

    return (
        <div className={cn(
            "bg-muted/30 p-4 rounded-xl min-w-[300px] w-full max-w-xs flex flex-col h-full border border-[hsl(var(--admin-border))] transition-colors",
            isOver && "bg-muted/60 border-[hsl(var(--brand-primary))]/30"
        )}>
            <div className="flex items-center justify-between mb-4">
                <h3 className="font-semibold capitalize text-sm flex items-center gap-2">
                    <span className={cn("w-2 h-2 rounded-full", colorClass.split(" ")[1].replace("text-", "bg-").replace("700", "500"))} />
                    {id}
                </h3>
                <span className={cn("text-xs font-medium px-2.5 py-0.5 rounded-full border", colorClass)}>
                    {leads.length}
                </span>
            </div>

            <div ref={setNodeRef} className="flex-1 overflow-y-auto min-h-[150px] scrollbar-thin scrollbar-thumb-muted-foreground/20">
                <SortableContext items={leads.map((l) => l.id)} strategy={verticalListSortingStrategy}>
                    <div className="space-y-3">
                        {leads.map((lead) => (
                            <LeadCard key={lead.id} lead={lead} onClick={onLeadClick} />
                        ))}
                    </div>
                </SortableContext>
                {leads.length === 0 && (
                    <div className={cn(
                        "h-32 flex items-center justify-center text-xs text-muted-foreground border-2 border-dashed border-muted rounded-lg mt-2 transition-colors",
                        isOver && "border-[hsl(var(--brand-primary))]/40 bg-[hsl(var(--brand-primary))]/5"
                    )}>
                        Drop items here
                    </div>
                )}
            </div>
        </div>
    );
};

const dropAnimation: DropAnimation = {
    sideEffects: defaultDropAnimationSideEffects({
        styles: {
            active: {
                opacity: '0.5',
            },
        },
    }),
};

export function LeadPipeline({ leads, onLeadMove, onLeadClick }: LeadPipelineProps) {
    const [activeId, setActiveId] = useState<string | null>(null);

    const sensors = useSensors(
        useSensor(PointerSensor, {
            activationConstraint: {
                distance: 8,
            },
        }),
        useSensor(KeyboardSensor, {
            coordinateGetter: sortableKeyboardCoordinates,
        })
    );

    const columns = leadStatusOptions;

    const handleDragStart = (event: DragStartEvent) => {
        setActiveId(event.active.id as string);
    };

    const handleDragEnd = (event: DragEndEvent) => {
        const { active, over } = event;

        if (!over) {
            setActiveId(null);
            return;
        }

        const activeLead = leads.find((l) => l.id === active.id);
        if (!activeLead) {
            setActiveId(null);
            return;
        }

        // Determine target status
        let newStatus = over.id as string;

        // If dropped on another lead, find that lead's status
        if (!columns.includes(newStatus as any)) {
            const overLead = leads.find((l) => l.id === over.id);
            if (overLead) {
                newStatus = overLead.status;
            }
        }

        if (activeLead.status !== newStatus && columns.includes(newStatus as any)) {
            onLeadMove(activeLead.id, newStatus);
        }

        setActiveId(null);
    };

    const getLeadsByStatus = (status: string) => {
        return leads.filter((l) => l.status === status);
    };

    const activeLead = activeId ? leads.find((l) => l.id === activeId) : null;

    return (
        <DndContext
            sensors={sensors}
            collisionDetection={closestCorners}
            onDragStart={handleDragStart}
            onDragEnd={handleDragEnd}
        >
            <div className="flex gap-4 overflow-x-auto pb-6 h-[calc(100vh-220px)] w-full px-1">
                {columns.map((status) => (
                    <Column
                        key={status}
                        id={status}
                        leads={getLeadsByStatus(status)}
                        onLeadClick={onLeadClick}
                    />
                ))}
            </div>

            <DragOverlay dropAnimation={dropAnimation}>
                {activeLead ? (
                    <div className="rotate-2 cursor-grabbing scale-105 shadow-xl rounded-xl">
                        <LeadCard lead={activeLead} onClick={() => { }} />
                    </div>
                ) : null}
            </DragOverlay>
        </DndContext>
    );
}

import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { formatDistanceToNow } from "date-fns";
import {
    User,
    MessageSquare,
    Phone,
    Mail,
    Calendar,
    ArrowRightLeft,
    FileText,
    Eye,
    Download
} from "lucide-react";

interface LeadTimelineProps {
    leadId: string;
}

const ActivityIcon = ({ type }: { type: string }) => {
    switch (type) {
        case 'lead_created': return <User className="h-4 w-4" />;
        case 'status_changed': return <ArrowRightLeft className="h-4 w-4" />;
        case 'note_added': return <FileText className="h-4 w-4" />;
        case 'email_sent': return <Mail className="h-4 w-4" />;
        case 'call_made': return <Phone className="h-4 w-4" />;
        case 'meeting_scheduled': return <Calendar className="h-4 w-4" />;
        case 'project_viewed': return <Eye className="h-4 w-4" />;
        case 'brochure_downloaded': return <Download className="h-4 w-4" />;
        default: return <MessageSquare className="h-4 w-4" />;
    }
};

export function LeadTimeline({ leadId }: LeadTimelineProps) {
    const { data: activities, isLoading } = useQuery({
        queryKey: ['lead-timeline', leadId],
        queryFn: async () => {
            const { data, error } = await supabase
                .from('lead_activities')
                .select(`
          *,
          profiles:performed_by (
            full_name,
            avatar_url
          )
        `)
                .eq('lead_id', leadId)
                .order('created_at', { ascending: false });

            if (error) throw error;
            return data;
        }
    });

    if (isLoading) return <div className="text-sm text-muted-foreground p-4">Loading history...</div>;

    if (!activities || activities.length === 0) {
        return <div className="text-sm text-muted-foreground p-4 bg-muted/30 rounded-lg text-center">No activity recorded yet.</div>;
    }

    return (
        <div className="space-y-6 pl-2">
            {activities.map((activity: any, index: number) => (
                <div key={activity.id} className="relative flex gap-4">
                    {/* Vertical Line */}
                    {index !== activities.length - 1 && (
                        <div className="absolute left-[19px] top-8 bottom-[-24px] w-px bg-border" />
                    )}

                    <div className="relative z-10 flex h-10 w-10 shrink-0 items-center justify-center rounded-full border bg-background text-muted-foreground shadow-sm">
                        <ActivityIcon type={activity.activity_type} />
                    </div>

                    <div className="flex-1 pb-1 pt-2">
                        <div className="flex items-center justify-between gap-2">
                            <span className="font-medium text-sm text-foreground">{activity.description}</span>
                            <time className="text-xs text-muted-foreground whitespace-nowrap">
                                {formatDistanceToNow(new Date(activity.created_at), { addSuffix: true })}
                            </time>
                        </div>

                        {activity.profiles && (
                            <p className="text-xs text-muted-foreground mt-1">
                                by {activity.profiles.full_name || "System"}
                            </p>
                        )}

                        {activity.metadata && Object.keys(activity.metadata).length > 0 && (
                            <div className="mt-2 text-xs bg-muted/50 p-2 rounded border font-mono">
                                {JSON.stringify(activity.metadata).slice(0, 100)}
                                {JSON.stringify(activity.metadata).length > 100 && "..."}
                            </div>
                        )}
                    </div>
                </div>
            ))}
        </div>
    );
}

import { Sheet, SheetContent, SheetHeader, SheetTitle, SheetDescription, SheetFooter } from "@/components/ui/sheet";
import { Button } from "@/components/ui/button";
import { Separator } from "@/components/ui/separator";
import {
    Download,
    Link,
    Trash2,
    Calendar,
    FileText,
    HardDrive,
    X,
    Sparkles,
    Loader2
} from "lucide-react";
import { format } from "date-fns";
import { Badge } from "@/components/ui/badge";
import { useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";

interface MediaFile {
    id: string;
    name: string;
    url: string;
    folder: string;
    size: number;
    created_at: string;
    alt?: string;
    caption?: string;
}

interface MediaDetailsSheetProps {
    file: MediaFile | null;
    open: boolean;
    onClose: () => void;
    onDelete: (file: MediaFile) => void;
    onCopyUrl: (url: string) => void;
}

export function MediaDetailsSheet({ file, open, onClose, onDelete, onCopyUrl }: MediaDetailsSheetProps) {
    const { toast } = useToast();
    const [isGenerating, setIsGenerating] = useState(false);
    const [aiMetadata, setAiMetadata] = useState<{ caption: string; altText: string } | null>(
        file ? { caption: file.caption || "", altText: file.alt || "" } : null
    );

    // Update local state when file changes
    if (file && aiMetadata === null && (file.caption || file.alt)) {
        setAiMetadata({ caption: file.caption || "", altText: file.alt || "" });
    }

    if (!file) return null;

    const handleGenerateCaption = async () => {
        setIsGenerating(true);
        try {
            const { data, error } = await supabase.functions.invoke('generate-caption', {
                body: {
                    imageUrl: file.url,
                    filePath: `${file.folder}/${file.name}`
                }
            });

            if (error) throw error;

            setAiMetadata(data);
            toast({ title: "AI Caption Generated!", description: "Metadata updated successfully." });
        } catch (error: any) {
            toast({
                title: "Generation Failed",
                description: error.message || "Could not generate caption.",
                variant: "destructive"
            });
        } finally {
            setIsGenerating(false);
        }
    };

    const formatFileSize = (bytes: number) => {
        if (bytes === 0) return "0 B";
        const k = 1024;
        const sizes = ["B", "KB", "MB", "GB"];
        const i = Math.floor(Math.log(bytes) / Math.log(k));
        return parseFloat((bytes / Math.pow(k, i)).toFixed(1)) + " " + sizes[i];
    };

    return (
        <Sheet open={open} onOpenChange={(val) => !val && onClose()}>
            <SheetContent className="w-[400px] sm:w-[540px] overflow-y-auto">
                <SheetHeader className="mb-6">
                    <SheetTitle>File Details</SheetTitle>
                </SheetHeader>

                <div className="space-y-6">
                    {/* Preview */}
                    <div className="rounded-lg border bg-muted/30 overflow-hidden flex items-center justify-center min-h-[300px] relative group">
                        <img
                            src={file.url}
                            alt={file.name}
                            className="w-full h-full object-contain max-h-[500px]"
                        />
                        <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                            <Button variant="secondary" onClick={() => window.open(file.url, '_blank')}>
                                Open Original
                            </Button>
                        </div>
                    </div>

                    {/* Metadata */}
                    <div className="space-y-4">
                        <div>
                            <h3 className="font-semibold text-lg break-all">{file.name}</h3>
                            <Badge variant="secondary" className="mt-2 capitalize">
                                {file.folder}
                            </Badge>
                        </div>

                        <Separator />

                        <div className="grid grid-cols-2 gap-4 text-sm">
                            <div className="flex items-center gap-2 text-muted-foreground">
                                <HardDrive className="w-4 h-4" />
                                <span>Size</span>
                            </div>
                            <div className="font-medium">{formatFileSize(file.size)}</div>

                            <div className="flex items-center gap-2 text-muted-foreground">
                                <Calendar className="w-4 h-4" />
                                <span>Uploaded</span>
                            </div>
                            <div className="font-medium">{format(new Date(file.created_at), "PPP p")}</div>

                            <div className="flex items-center gap-2 text-muted-foreground">
                                <FileText className="w-4 h-4" />
                                <span>Type</span>
                            </div>
                            <div className="font-medium uppercase">{file.name.split('.').pop() || 'Unknown'}</div>
                        </div>
                    </div>

                </div>


                <Separator />

                {/* AI Features */}
                <div className="space-y-4">
                    <div className="flex items-center justify-between">
                        <div className="flex items-center gap-2">
                            <div className="p-1.5 bg-purple-100 rounded-md">
                                <Sparkles className="w-4 h-4 text-purple-600" />
                            </div>
                            <div>
                                <h3 className="font-semibold text-sm">AI Intelligence</h3>
                                <p className="text-xs text-muted-foreground">Auto-generate captions & alt text</p>
                            </div>
                        </div>
                        <Button
                            variant="outline"
                            size="sm"
                            onClick={handleGenerateCaption}
                            disabled={isGenerating}
                            className="h-8 border-purple-200 bg-purple-50 text-purple-700 hover:bg-purple-100 hover:text-purple-800 transition-colors"
                        >
                            {isGenerating ? (
                                <>
                                    <Loader2 className="w-3 h-3 mr-2 animate-spin" />
                                    Analyzing...
                                </>
                            ) : (
                                <>
                                    <Sparkles className="w-3 h-3 mr-2" />
                                    Generate Metadata
                                </>
                            )}
                        </Button>
                    </div>

                    {aiMetadata ? (
                        <div className="rounded-xl border border-purple-100 bg-gradient-to-br from-purple-50/50 to-white p-4 space-y-4 animate-in fade-in slide-in-from-top-2 shadow-sm">
                            <div className="space-y-2">
                                <div className="flex items-center justify-between">
                                    <span className="text-xs font-semibold text-purple-900 uppercase tracking-wider">Caption</span>
                                    <Badge variant="outline" className="text-[10px] border-purple-200 text-purple-700 bg-purple-50/50">
                                        AI Generated
                                    </Badge>
                                </div>
                                <p className="text-sm text-foreground/90 leading-relaxed bg-white/50 p-2 rounded-md border border-purple-100/50">
                                    {aiMetadata.caption}
                                </p>
                            </div>

                            <div className="space-y-2">
                                <span className="text-xs font-semibold text-purple-900 uppercase tracking-wider">Alt Text</span>
                                <p className="text-sm text-muted-foreground italic bg-white/50 p-2 rounded-md border border-purple-100/50">
                                    {aiMetadata.altText}
                                </p>
                            </div>
                        </div>
                    ) : (
                        <div className="rounded-xl border border-dashed p-6 text-center bg-muted/20">
                            <p className="text-sm text-muted-foreground">
                                Generate AI metadata to improve SEO and accessibility.
                            </p>
                        </div>
                    )}
                </div>

                <Separator />

                {/* Actions */}
                <div className="grid grid-cols-2 gap-3">
                    <Button variant="outline" onClick={() => onCopyUrl(file.url)} className="w-full">
                        <Link className="w-4 h-4 mr-2" />
                        Copy Link
                    </Button>
                    <Button variant="outline" onClick={() => {
                        const link = document.createElement('a');
                        link.href = file.url;
                        link.download = file.name;
                        document.body.appendChild(link);
                        link.click();
                        document.body.removeChild(link);
                    }} className="w-full">
                        <Download className="w-4 h-4 mr-2" />
                        Download
                    </Button>
                    <Button
                        variant="destructive"
                        onClick={() => { onDelete(file); onClose(); }}
                        className="col-span-2"
                    >
                        <Trash2 className="w-4 h-4 mr-2" />
                        Delete File
                    </Button>
                </div>
            </SheetContent>
        </Sheet>
    );
}

import { motion } from "framer-motion";
