import { useState, useEffect } from "react";
import { motion } from "framer-motion";
import { Plus, Pencil, Trash2, Loader2, Eye, EyeOff } from "lucide-react";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { useToast } from "@/hooks/use-toast";
import { supabase } from "@/integrations/supabase/client";
import { format } from "date-fns";
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from "@/components/ui/breadcrumb";
import { RichTextEditor } from "@/components/admin/blogs/RichTextEditor";
import { MediaPicker } from "@/components/admin/media/MediaPicker";
import { Image as ImageIcon } from "lucide-react";

interface BlogPost {
  id: string;
  title: string;
  slug: string;
  excerpt: string | null;
  content: string | null;
  cover_image: string | null;
  is_published: boolean;
  published_at: string | null;
  created_at: string;
}

const AdminBlogs = () => {
  const [posts, setPosts] = useState<BlogPost[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [editingPost, setEditingPost] = useState<BlogPost | null>(null);
  const [formData, setFormData] = useState({
    title: "",
    slug: "",
    excerpt: "",
    content: "",
    cover_image: "",
    is_published: false
  });
  const [isSaving, setIsSaving] = useState(false);
  const { toast } = useToast();

  useEffect(() => {
    fetchPosts();
  }, []);

  const fetchPosts = async () => {
    const { data, error } = await supabase
      .from('blogs')
      .select('*')
      .order('created_at', { ascending: false });

    if (data) {
      setPosts(data);
    }
    setIsLoading(false);
  };

  const generateSlug = (title: string) => {
    return title
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/(^-|-$)/g, '');
  };

  const handleTitleChange = (title: string) => {
    setFormData({
      ...formData,
      title,
      slug: generateSlug(title)
    });
  };


  const handleDelete = async (id: string) => {
    if (!confirm('Are you sure you want to delete this post?')) return;

    const { error } = await supabase
      .from('blogs')
      .delete()
      .eq('id', id);

    if (error) {
      toast({
        title: "Error deleting post",
        variant: "destructive",
      });
    } else {
      toast({ title: "Post deleted successfully" });
      fetchPosts();
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);

    try {
      const postData = {
        title: formData.title,
        slug: formData.slug,
        excerpt: formData.excerpt,
        content: formData.content,
        cover_image: formData.cover_image || null,
        is_published: formData.is_published,
        published_at: formData.is_published ? new Date().toISOString() : null
      };

      if (editingPost) {
        const { error } = await supabase
          .from('blogs')
          .update(postData)
          .eq('id', editingPost.id);
        if (error) throw error;
      } else {
        const { error } = await supabase
          .from('blogs')
          .insert(postData);
        if (error) throw error;
      }

      toast({
        title: editingPost ? "Post updated!" : "Post updated!",
      });

      // Clear draft
      const draftKey = editingPost ? `admin_blog_draft_${editingPost.id}` : "admin_blog_draft_new";
      localStorage.removeItem(draftKey);

      setIsDialogOpen(false);
      setEditingPost(null);
      resetForm();
      fetchPosts();
    } catch (error: any) {
      toast({
        title: "Error saving post",
        description: error.message,
        variant: "destructive",
      });
    } finally {
      setIsSaving(false);
    }
  };

  // Auto-save draft logic
  useEffect(() => {
    if (!isDialogOpen) return;

    const saveDraft = setTimeout(() => {
      const draftKey = editingPost ? `admin_blog_draft_${editingPost.id}` : "admin_blog_draft_new";
      // Only save if there's actual content to save
      if (formData.title || formData.content || formData.excerpt) {
        localStorage.setItem(draftKey, JSON.stringify(formData));
      }
    }, 1000);

    return () => clearTimeout(saveDraft);
  }, [formData, editingPost, isDialogOpen]);

  const handleNewPost = () => {
    setEditingPost(null);
    const savedDraft = localStorage.getItem("admin_blog_draft_new");
    if (savedDraft) {
      try {
        const parsed = JSON.parse(savedDraft);
        setFormData(parsed);
        toast({
          title: "Draft Restored",
          description: "We found an unsaved draft and restored it for you.",
        });
      } catch (e) {
        console.error("Failed to parse draft", e);
        resetForm();
      }
    } else {
      resetForm();
    }
    setIsDialogOpen(true);
  };

  const handleEdit = (post: BlogPost) => {
    setEditingPost(post);
    const savedDraft = localStorage.getItem(`admin_blog_draft_${post.id}`);

    if (savedDraft) {
      try {
        const parsed = JSON.parse(savedDraft);
        setFormData(parsed);
        toast({
          title: "Draft Restored",
          description: "Restored your unsaved changes for this post.",
        });
      } catch (e) {
        setFormData({
          title: post.title,
          slug: post.slug,
          excerpt: post.excerpt || "",
          content: post.content || "",
          cover_image: post.cover_image || "",
          is_published: post.is_published
        });
      }
    } else {
      setFormData({
        title: post.title,
        slug: post.slug,
        excerpt: post.excerpt || "",
        content: post.content || "",
        cover_image: post.cover_image || "",
        is_published: post.is_published
      });
    }
    setIsDialogOpen(true);
  };

  const resetForm = () => {
    setFormData({
      title: "",
      slug: "",
      excerpt: "",
      content: "",
      cover_image: "",
      is_published: false
    });
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-64">
        <Loader2 className="w-8 h-8 animate-spin text-primary" />
      </div>
    );
  }

  return (
    <div className="space-y-8">
      <Breadcrumb>
        <BreadcrumbList>
          <BreadcrumbItem>
            <BreadcrumbLink href="/admin">Admin</BreadcrumbLink>
          </BreadcrumbItem>
          <BreadcrumbSeparator />
          <BreadcrumbItem>
            <BreadcrumbPage>Blogs</BreadcrumbPage>
          </BreadcrumbItem>
        </BreadcrumbList>
      </Breadcrumb>

      <div className="flex items-center justify-between">
        <div>
          <h1 className="font-display text-3xl font-bold">Blog Posts</h1>
          <p className="text-muted-foreground mt-1">Manage your blog content</p>
        </div>
        <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
          <DialogTrigger asChild>
            <Button variant="gold" onClick={handleNewPost}>
              <Plus className="w-4 h-4 mr-2" />
              New Post
            </Button>
          </DialogTrigger>
          <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
            <DialogHeader>
              <DialogTitle>
                {editingPost ? "Edit Post" : "New Blog Post"}
              </DialogTitle>
            </DialogHeader>
            <form onSubmit={handleSubmit} className="space-y-6">
              <div className="grid gap-6 md:grid-cols-3">
                {/* Main Content Column */}
                <div className="md:col-span-2 space-y-4">
                  <div className="space-y-2">
                    <div className="flex justify-between">
                      <Label>Title</Label>
                      <span className={`text-xs ${formData.title.length > 60 ? "text-red-500" : "text-muted-foreground"}`}>
                        {formData.title.length}/60
                      </span>
                    </div>
                    <Input
                      value={formData.title}
                      onChange={(e) => handleTitleChange(e.target.value)}
                      required
                      placeholder="Enter a catchy title..."
                    />
                  </div>
                  <div className="space-y-2">
                    <Label>Slug</Label>
                    <div className="flex gap-2">
                      <Input
                        value={formData.slug}
                        onChange={(e) => setFormData({ ...formData, slug: e.target.value })}
                        required
                        className="font-mono text-sm"
                      />
                      <Button
                        type="button"
                        variant="ghost"
                        size="icon"
                        onClick={() => setFormData(prev => ({ ...prev, slug: generateSlug(prev.title) }))}
                        title="Regenerate from title"
                      >
                        <Loader2 className="w-4 h-4" />
                      </Button>
                    </div>
                  </div>
                  <div className="space-y-2">
                    <Label>Content</Label>
                    <RichTextEditor
                      content={formData.content || ""}
                      onChange={(content) => setFormData({ ...formData, content })}
                      className="min-h-[400px]"
                    />
                  </div>
                </div>

                {/* Sidebar Column */}
                <div className="space-y-6">
                  <div className="space-y-2">
                    <div className="flex justify-between">
                      <Label>Excerpt</Label>
                      <span className={`text-xs ${formData.excerpt.length > 160 ? "text-red-500" : "text-muted-foreground"}`}>
                        {formData.excerpt.length}/160
                      </span>
                    </div>
                    <Textarea
                      value={formData.excerpt}
                      onChange={(e) => setFormData({ ...formData, excerpt: e.target.value })}
                      rows={5}
                      placeholder="Short summary for SEO and previews..."
                    />
                  </div>

                  <div className="space-y-2">
                    <Label>Cover Image</Label>
                    <div className="border-2 border-dashed rounded-lg p-4 text-center hover:bg-muted/50 transition-colors">
                      {formData.cover_image ? (
                        <div className="relative group">
                          <img src={formData.cover_image} alt="Cover" className="h-32 w-full object-cover rounded-md" />
                          <Button
                            type="button"
                            variant="destructive"
                            size="icon"
                            className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition-opacity"
                            onClick={() => setFormData({ ...formData, cover_image: "" })}
                          >
                            <Trash2 className="h-4 w-4" />
                          </Button>
                        </div>
                      ) : (
                        <div className="py-4 text-muted-foreground text-sm flex flex-col items-center gap-2">
                          <MediaPicker
                            onSelect={(url) => setFormData({ ...formData, cover_image: url })}
                            trigger={
                              <Button type="button" variant="outline" className="gap-2">
                                <ImageIcon className="w-4 h-4" />
                                Select from Library
                              </Button>
                            }
                          />
                          <span className="text-xs text-muted-foreground">or paste URL</span>
                          <Input
                            value={formData.cover_image || ""}
                            onChange={(e) => setFormData({ ...formData, cover_image: e.target.value })}
                            placeholder="https://..."
                            className="mt-2"
                          />
                        </div>
                      )}
                    </div>
                  </div>

                  <div className="bg-muted/30 p-4 rounded-lg space-y-4 border">
                    <div className="flex items-center justify-between">
                      <Label htmlFor="publish-switch" className="flex flex-col gap-1 cursor-pointer">
                        <span>Publish Status</span>
                        <span className="text-xs text-muted-foreground font-normal">
                          {formData.is_published ? "Visible to public" : "Draft mode"}
                        </span>
                      </Label>
                      <Switch
                        id="publish-switch"
                        checked={formData.is_published}
                        onCheckedChange={(checked) => setFormData({ ...formData, is_published: checked })}
                      />
                    </div>
                  </div>
                </div>
              </div>

              <div className="flex justify-end gap-2 pt-4 border-t">
                <Button type="button" variant="outline" onClick={() => setIsDialogOpen(false)}>
                  Cancel
                </Button>
                <Button type="submit" variant="gold" disabled={isSaving}>
                  {isSaving ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : null}
                  {editingPost ? "Update" : "Create"} Post
                </Button>
              </div>
            </form>
          </DialogContent>
        </Dialog>
      </div>

      <div className="grid gap-4">
        {posts.map((post, index) => (
          <motion.div
            key={post.id}
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: index * 0.05 }}
          >
            <Card className="bg-card border-border">
              <CardContent className="p-6">
                <div className="flex items-start justify-between gap-4">
                  <div className="flex-1">
                    <div className="flex items-center gap-2 mb-2">
                      {post.is_published ? (
                        <Eye className="w-4 h-4 text-green-500" />
                      ) : (
                        <EyeOff className="w-4 h-4 text-muted-foreground" />
                      )}
                      <span className={`text-xs ${post.is_published ? 'text-green-500' : 'text-muted-foreground'}`}>
                        {post.is_published ? 'Published' : 'Draft'}
                      </span>
                    </div>
                    <h3 className="font-semibold text-lg mb-1">{post.title}</h3>
                    <p className="text-muted-foreground text-sm line-clamp-2 mb-2">
                      {post.excerpt}
                    </p>
                    <p className="text-xs text-muted-foreground">
                      Created {format(new Date(post.created_at), 'MMM dd, yyyy')}
                    </p>
                  </div>
                  <div className="flex gap-2">
                    <Button size="sm" variant="outline" onClick={() => handleEdit(post)}>
                      <Pencil className="w-4 h-4" />
                    </Button>
                    <Button size="sm" variant="outline" onClick={() => handleDelete(post.id)}>
                      <Trash2 className="w-4 h-4 text-destructive" />
                    </Button>
                  </div>
                </div>
              </CardContent>
            </Card>
          </motion.div>
        ))}

        {posts.length === 0 && (
          <div className="text-center py-12 text-muted-foreground">
            No blog posts yet. Create your first post!
          </div>
        )}
      </div>
    </div>
  );
};

export default AdminBlogs;

import { useState, useMemo } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from "@/components/ui/table";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select";
import {
    Breadcrumb,
    BreadcrumbItem,
    BreadcrumbLink,
    BreadcrumbList,
    BreadcrumbPage,
    BreadcrumbSeparator,
} from "@/components/ui/breadcrumb";
import {
    Download,
    Search,
    Loader2,
    Calculator,
    Flame,
    Thermometer,
    Snowflake,
    ArrowUpDown,
} from "lucide-react";
import { useToast } from "@/hooks/use-toast";
import { format } from "date-fns";
import { EmptyState } from "@/components/admin/EmptyState";
import { EstimateStatsRow } from "@/components/admin/estimates/EstimateStatsRow";
import { EstimateLeadDetailSheet } from "@/components/admin/estimates/EstimateLeadDetailSheet";

type SortField = "created_at" | "lead_score" | "estimate_total_max" | "area" | "name";
type SortDir = "asc" | "desc";

const categoryConfig = {
    HOT: { icon: Flame, color: "text-red-500", bg: "bg-red-500/10", border: "border-red-500/30" },
    WARM: { icon: Thermometer, color: "text-amber-500", bg: "bg-amber-500/10", border: "border-amber-500/30" },
    COLD: { icon: Snowflake, color: "text-blue-500", bg: "bg-blue-500/10", border: "border-blue-500/30" },
};

const statusColors: Record<string, string> = {
    new: "bg-emerald-500/10 text-emerald-600 border-emerald-500/30",
    contacted: "bg-blue-500/10 text-blue-600 border-blue-500/30",
    converted: "bg-purple-500/10 text-purple-600 border-purple-500/30",
    archived: "bg-gray-500/10 text-gray-500 border-gray-500/30",
};

const formatCurrency = (val: number) =>
    new Intl.NumberFormat("en-IN", { style: "currency", currency: "INR", maximumFractionDigits: 0 }).format(val);

export default function AdminEstimateLeads() {
    const [search, setSearch] = useState("");
    const [categoryFilter, setCategoryFilter] = useState<string>("all");
    const [statusFilter, setStatusFilter] = useState<string>("all");
    const [sortField, setSortField] = useState<SortField>("created_at");
    const [sortDir, setSortDir] = useState<SortDir>("desc");
    const [selectedLead, setSelectedLead] = useState<any | null>(null);
    const [isSheetOpen, setIsSheetOpen] = useState(false);

    const { toast } = useToast();
    const queryClient = useQueryClient();

    // Fetch estimate leads
    const { data: leads = [], isLoading } = useQuery({
        queryKey: ["estimate-leads"],
        queryFn: async () => {
            const { data, error } = await supabase
                .from("estimate_leads")
                .select("*")
                .order("created_at", { ascending: false });

            if (error) throw error;
            return data || [];
        },
    });

    // Update mutation
    const updateMutation = useMutation({
        mutationFn: async ({ id, ...updates }: any) => {
            const { error } = await supabase
                .from("estimate_leads")
                .update({ ...updates, updated_at: new Date().toISOString() })
                .eq("id", id);
            if (error) throw error;
        },
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ["estimate-leads"] });
            toast({ title: "Lead Updated", description: "Changes saved successfully." });
            setIsSheetOpen(false);
        },
        onError: (err: any) => {
            toast({ variant: "destructive", title: "Error", description: err.message });
        },
    });

    // Delete mutation
    const deleteMutation = useMutation({
        mutationFn: async (id: string) => {
            const { error } = await supabase.from("estimate_leads").delete().eq("id", id);
            if (error) throw error;
        },
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ["estimate-leads"] });
            toast({ title: "Lead Deleted", description: "Estimate lead removed." });
            setIsSheetOpen(false);
        },
    });

    // Filter & sort
    const filteredLeads = useMemo(() => {
        let result = [...leads];

        if (search) {
            const q = search.toLowerCase();
            result = result.filter(
                (l: any) =>
                    l.name?.toLowerCase().includes(q) ||
                    l.email?.toLowerCase().includes(q) ||
                    l.city?.toLowerCase().includes(q) ||
                    l.phone?.includes(q)
            );
        }

        if (categoryFilter !== "all") {
            result = result.filter((l: any) => l.lead_category === categoryFilter);
        }

        if (statusFilter !== "all") {
            result = result.filter((l: any) => l.status === statusFilter);
        }

        result.sort((a: any, b: any) => {
            const aVal = a[sortField] ?? 0;
            const bVal = b[sortField] ?? 0;
            if (typeof aVal === "string") {
                return sortDir === "asc" ? aVal.localeCompare(bVal) : bVal.localeCompare(aVal);
            }
            return sortDir === "asc" ? aVal - bVal : bVal - aVal;
        });

        return result;
    }, [leads, search, categoryFilter, statusFilter, sortField, sortDir]);

    // Stats
    const stats = useMemo(() => {
        const total = leads.length;
        const hot = leads.filter((l: any) => l.lead_category === "HOT").length;
        const converted = leads.filter((l: any) => l.status === "converted").length;
        const avgEstimate =
            total > 0
                ? leads.reduce((sum: number, l: any) => sum + ((l.estimate_total_min + l.estimate_total_max) / 2 || 0), 0) / total
                : 0;
        const conversionRate = total > 0 ? (converted / total) * 100 : 0;
        return { total, hot, avgEstimate, conversionRate };
    }, [leads]);

    const toggleSort = (field: SortField) => {
        if (sortField === field) {
            setSortDir((d) => (d === "asc" ? "desc" : "asc"));
        } else {
            setSortField(field);
            setSortDir("desc");
        }
    };

    const handleExport = () => {
        const csvContent = [
            ["Name", "Email", "Phone", "City", "Area", "Budget", "Design Package", "Timeline", "Est Min", "Est Max", "Score", "Category", "Status", "Date"],
            ...leads.map((l: any) => [
                l.name, l.email, l.phone, l.city, l.area, l.budget, l.design_package, l.timeline,
                l.estimate_total_min, l.estimate_total_max, l.lead_score, l.lead_category, l.status,
                l.created_at,
            ]),
        ]
            .map((row) => row.join(","))
            .join("\n");

        const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
        const link = document.createElement("a");
        link.href = URL.createObjectURL(blob);
        link.download = `estimate_leads_${format(new Date(), "yyyy-MM-dd")}.csv`;
        link.click();
    };

    return (
        <div className="flex flex-col space-y-6 animate-in fade-in duration-500">
            <Breadcrumb>
                <BreadcrumbList>
                    <BreadcrumbItem>
                        <BreadcrumbLink href="/admin">Admin</BreadcrumbLink>
                    </BreadcrumbItem>
                    <BreadcrumbSeparator />
                    <BreadcrumbItem>
                        <BreadcrumbPage>Estimate Leads</BreadcrumbPage>
                    </BreadcrumbItem>
                </BreadcrumbList>
            </Breadcrumb>

            <div className="flex items-center justify-between">
                <div>
                    <h2 className="text-3xl font-display font-bold text-[hsl(var(--admin-foreground))]">
                        Estimate Leads
                    </h2>
                    <p className="text-[hsl(var(--admin-muted))]">
                        Manage leads from the cost estimator.
                    </p>
                </div>
                <Button variant="outline" onClick={handleExport}>
                    <Download className="mr-2 h-4 w-4" /> Export CSV
                </Button>
            </div>

            {/* Stats */}
            <EstimateStatsRow
                totalLeads={stats.total}
                hotLeads={stats.hot}
                avgEstimate={stats.avgEstimate}
                conversionRate={stats.conversionRate}
                isLoading={isLoading}
            />

            {/* Filters */}
            <div className="flex flex-wrap items-center gap-3">
                <div className="relative flex-1 max-w-sm">
                    <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-muted-foreground" />
                    <Input
                        placeholder="Search by name, email, city..."
                        className="pl-9"
                        value={search}
                        onChange={(e) => setSearch(e.target.value)}
                    />
                </div>
                <Select value={categoryFilter} onValueChange={setCategoryFilter}>
                    <SelectTrigger className="w-[140px]">
                        <SelectValue placeholder="Category" />
                    </SelectTrigger>
                    <SelectContent>
                        <SelectItem value="all">All Categories</SelectItem>
                        <SelectItem value="HOT">🔥 Hot</SelectItem>
                        <SelectItem value="WARM">🌡️ Warm</SelectItem>
                        <SelectItem value="COLD">❄️ Cold</SelectItem>
                    </SelectContent>
                </Select>
                <Select value={statusFilter} onValueChange={setStatusFilter}>
                    <SelectTrigger className="w-[140px]">
                        <SelectValue placeholder="Status" />
                    </SelectTrigger>
                    <SelectContent>
                        <SelectItem value="all">All Status</SelectItem>
                        <SelectItem value="new">New</SelectItem>
                        <SelectItem value="contacted">Contacted</SelectItem>
                        <SelectItem value="converted">Converted</SelectItem>
                        <SelectItem value="archived">Archived</SelectItem>
                    </SelectContent>
                </Select>
            </div>

            {/* Table */}
            {isLoading ? (
                <div className="flex-1 flex items-center justify-center py-20">
                    <Loader2 className="h-8 w-8 animate-spin text-primary" />
                </div>
            ) : filteredLeads.length === 0 ? (
                <EmptyState
                    icon={Calculator}
                    title="No estimate leads found"
                    description={
                        search || categoryFilter !== "all" || statusFilter !== "all"
                            ? "Try adjusting your filters"
                            : "Leads will appear here when users submit estimates"
                    }
                />
            ) : (
                <div className="border rounded-lg bg-card overflow-auto">
                    <Table>
                        <TableHeader>
                            <TableRow>
                                <TableHead
                                    className="cursor-pointer hover:text-foreground"
                                    onClick={() => toggleSort("name")}
                                >
                                    <div className="flex items-center gap-1">
                                        Name
                                        <ArrowUpDown className="h-3 w-3" />
                                    </div>
                                </TableHead>
                                <TableHead>Location</TableHead>
                                <TableHead
                                    className="cursor-pointer hover:text-foreground"
                                    onClick={() => toggleSort("area")}
                                >
                                    <div className="flex items-center gap-1">
                                        Area
                                        <ArrowUpDown className="h-3 w-3" />
                                    </div>
                                </TableHead>
                                <TableHead
                                    className="cursor-pointer hover:text-foreground"
                                    onClick={() => toggleSort("estimate_total_max")}
                                >
                                    <div className="flex items-center gap-1">
                                        Estimate
                                        <ArrowUpDown className="h-3 w-3" />
                                    </div>
                                </TableHead>
                                <TableHead
                                    className="cursor-pointer hover:text-foreground"
                                    onClick={() => toggleSort("lead_score")}
                                >
                                    <div className="flex items-center gap-1">
                                        Score
                                        <ArrowUpDown className="h-3 w-3" />
                                    </div>
                                </TableHead>
                                <TableHead>Category</TableHead>
                                <TableHead>Status</TableHead>
                                <TableHead
                                    className="cursor-pointer hover:text-foreground"
                                    onClick={() => toggleSort("created_at")}
                                >
                                    <div className="flex items-center gap-1">
                                        Date
                                        <ArrowUpDown className="h-3 w-3" />
                                    </div>
                                </TableHead>
                                <TableHead className="text-right">Actions</TableHead>
                            </TableRow>
                        </TableHeader>
                        <TableBody>
                            {filteredLeads.map((lead: any) => {
                                const cat = categoryConfig[lead.lead_category as keyof typeof categoryConfig] || categoryConfig.COLD;
                                const CatIcon = cat.icon;
                                return (
                                    <TableRow
                                        key={lead.id}
                                        className="cursor-pointer hover:bg-muted/50"
                                        onClick={() => {
                                            setSelectedLead(lead);
                                            setIsSheetOpen(true);
                                        }}
                                    >
                                        <TableCell>
                                            <div>
                                                <p className="font-medium">{lead.name}</p>
                                                <p className="text-xs text-muted-foreground">{lead.email}</p>
                                            </div>
                                        </TableCell>
                                        <TableCell>
                                            <div className="text-sm">
                                                <p>{lead.city || "—"}</p>
                                                {lead.city_tier && (
                                                    <p className="text-xs text-muted-foreground">{lead.city_tier}</p>
                                                )}
                                            </div>
                                        </TableCell>
                                        <TableCell className="text-sm">
                                            {lead.area?.toLocaleString()} sq ft
                                        </TableCell>
                                        <TableCell className="text-sm font-medium">
                                            {formatCurrency(lead.estimate_total_min)} –{" "}
                                            {formatCurrency(lead.estimate_total_max)}
                                        </TableCell>
                                        <TableCell>
                                            <div className="flex items-center gap-1.5">
                                                <div className="w-8 h-8 rounded-full bg-muted flex items-center justify-center text-xs font-bold">
                                                    {lead.lead_score}
                                                </div>
                                            </div>
                                        </TableCell>
                                        <TableCell>
                                            <Badge variant="outline" className={`${cat.bg} ${cat.color} ${cat.border}`}>
                                                <CatIcon className="w-3 h-3 mr-1" />
                                                {lead.lead_category}
                                            </Badge>
                                        </TableCell>
                                        <TableCell>
                                            <Badge variant="outline" className={`capitalize ${statusColors[lead.status] || ""}`}>
                                                {lead.status}
                                            </Badge>
                                        </TableCell>
                                        <TableCell className="text-sm text-muted-foreground">
                                            {format(new Date(lead.created_at), "MMM d, yyyy")}
                                        </TableCell>
                                        <TableCell className="text-right">
                                            <Button variant="ghost" size="sm">
                                                View
                                            </Button>
                                        </TableCell>
                                    </TableRow>
                                );
                            })}
                        </TableBody>
                    </Table>
                </div>
            )}

            <EstimateLeadDetailSheet
                lead={selectedLead}
                open={isSheetOpen}
                onOpenChange={setIsSheetOpen}
                onSave={(updated) => updateMutation.mutate(updated)}
                onDelete={(id) => deleteMutation.mutate(id)}
            />
        </div>
    );
}

import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { LeadPipeline } from "@/components/admin/leads/LeadPipeline";
import { LeadDetailSheet } from "@/components/admin/leads/LeadDetailSheet";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { LayoutGrid, List as ListIcon, Loader2, Download, Search, Plus, Users } from "lucide-react";
import { useToast } from "@/hooks/use-toast";
import { format } from "date-fns";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { calculateLeadScore, Lead } from "@/lib/leadScoring";
import { EmptyState } from "@/components/admin/EmptyState";
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from "@/components/ui/breadcrumb";

export default function AdminLeads() {
  const [view, setView] = useState<"board" | "list">("board");
  const [search, setSearch] = useState("");
  const [selectedLead, setSelectedLead] = useState<any | null>(null);
  const [isSheetOpen, setIsSheetOpen] = useState(false);

  const { toast } = useToast();
  const queryClient = useQueryClient();

  // Fetch Leads
  const { data: leads = [], isLoading } = useQuery({
    queryKey: ["leads"],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("leads")
        .select("*")
        .order("created_at", { ascending: false });

      if (error) throw error;

      const leadsWithScore = (data as unknown as Lead[]).map(lead => ({
        ...lead,
        score: lead.score ?? calculateLeadScore(lead)
      }));

      return leadsWithScore.sort((a, b) => (b.score || 0) - (a.score || 0));
    },
  });

  // Filter Leads
  const filteredLeads = leads.filter((lead) =>
    lead.name?.toLowerCase().includes(search.toLowerCase()) ||
    lead.email?.toLowerCase().includes(search.toLowerCase())
  );

  // Update Lead Mutation
  const updateMutation = useMutation({
    mutationFn: async ({ id, ...updates }: any) => {
      const { error } = await supabase.from("leads").update(updates).eq("id", id);
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["leads"] });
      toast({ title: "Lead Updated", description: "Changes saved successfully." });
      setIsSheetOpen(false);
    },
    onError: (err) => {
      toast({ variant: "destructive", title: "Error", description: err.message });
    },
  });

  // Delete Lead Mutation
  const deleteMutation = useMutation({
    mutationFn: async (id: string) => {
      const { error } = await supabase.from("leads").delete().eq("id", id);
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["leads"] });
      toast({ title: "Lead Deleted", description: "Lead removed permanently." });
      setIsSheetOpen(false);
    },
  });

  const handleDragMove = (leadId: string, newStatus: string) => {
    // Optimistic update could go here, but for now we'll just trigger mutation
    updateMutation.mutate({ id: leadId, status: newStatus });
  };

  const handleExport = () => {
    const csvContent = [
      ["Name", "Email", "Phone", "Service", "Status", "Date"],
      ...leads.map((l) => [l.name, l.email, l.phone, l.service, l.status, l.created_at])
    ].map(e => e.join(",")).join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `leads_export_${format(new Date(), "yyyy-MM-dd")}.csv`;
    link.click();
  };

  return (
    <div className="h-[calc(100vh-100px)] flex flex-col space-y-4">
      <Breadcrumb>
        <BreadcrumbList>
          <BreadcrumbItem>
            <BreadcrumbLink href="/admin">Admin</BreadcrumbLink>
          </BreadcrumbItem>
          <BreadcrumbSeparator />
          <BreadcrumbItem>
            <BreadcrumbPage>Leads</BreadcrumbPage>
          </BreadcrumbItem>
        </BreadcrumbList>
      </Breadcrumb>

      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-3xl font-display font-bold text-[hsl(var(--admin-foreground))]">Leads CRM</h2>
          <p className="text-[hsl(var(--admin-muted))]">Manage your sales pipeline.</p>
        </div>
        <div className="flex items-center gap-2">
          <Button variant="outline" onClick={handleExport}>
            <Download className="mr-2 h-4 w-4" /> Export CSV
          </Button>
          <Button onClick={() => setIsSheetOpen(true)}>
            <Plus className="mr-2 h-4 w-4" /> Add Lead
          </Button>
        </div>
      </div>

      <div className="flex items-center justify-between gap-4">
        <div className="relative flex-1 max-w-sm">
          <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-muted-foreground" />
          <Input
            placeholder="Search leads..."
            className="pl-9"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </div>
        <Tabs value={view} onValueChange={(v) => setView(v as "board" | "list")}>
          <TabsList>
            <TabsTrigger value="board"><LayoutGrid className="mr-2 h-4 w-4" /> Board</TabsTrigger>
            <TabsTrigger value="list"><ListIcon className="mr-2 h-4 w-4" /> List</TabsTrigger>
          </TabsList>
        </Tabs>
      </div>

      {isLoading ? (
        <div className="flex-1 flex items-center justify-center">
          <Loader2 className="h-8 w-8 animate-spin text-primary" />
        </div>
      ) : filteredLeads.length === 0 ? (
        <EmptyState
          icon={Users}
          title="No leads found"
          description={search ? "Try adjusting your search criteria" : "Start capturing leads to build your sales pipeline"}
          primaryAction={{
            label: "Add Lead",
            onClick: () => setIsSheetOpen(true),
            icon: Plus
          }}
        />
      ) : (
        <div className="flex-1 overflow-hidden">
          {view === "board" ? (
            <LeadPipeline
              leads={filteredLeads}
              onLeadMove={handleDragMove}
              onLeadClick={(lead) => { setSelectedLead(lead); setIsSheetOpen(true); }}
            />
          ) : (
            <div className="border rounded-md bg-white">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Name</TableHead>
                    <TableHead>Service</TableHead>
                    <TableHead>Status</TableHead>
                    <TableHead>Date</TableHead>
                    <TableHead className="text-right">Actions</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {filteredLeads.map((lead) => (
                    <TableRow key={lead.id} className="cursor-pointer hover:bg-muted/50" onClick={() => { setSelectedLead(lead); setIsSheetOpen(true); }}>
                      <TableCell className="font-medium">{lead.name}</TableCell>
                      <TableCell>{lead.service}</TableCell>
                      <TableCell>
                        <Badge variant="outline" className="capitalize">{lead.status}</Badge>
                      </TableCell>
                      <TableCell>{format(new Date(lead.created_at), "MMM d, yyyy")}</TableCell>
                      <TableCell className="text-right">
                        <Button variant="ghost" size="sm">View</Button>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
          )}
        </div>
      )}

      <LeadDetailSheet
        lead={selectedLead}
        open={isSheetOpen}
        onOpenChange={setIsSheetOpen}
        onSave={(updated) => updateMutation.mutate(updated)}
        onDelete={(id) => deleteMutation.mutate(id)}
      />
    </div>
  );
}

import { useState, useEffect } from "react";
import { motion } from "framer-motion";
import {
    Loader2,
    Search,
    FolderOpen,
    Grid,
    List,
    CheckSquare,
    Square,
    Trash2
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select";
import { useToast } from "@/hooks/use-toast";
import { supabase } from "@/integrations/supabase/client";
import { ConfirmDialog } from "@/components/admin/ConfirmDialog";
import { MediaGrid } from "@/components/admin/media/MediaGrid";
import { MediaUploadZone } from "@/components/admin/media/MediaUploadZone";
import { MediaDetailsSheet } from "@/components/admin/media/MediaDetailsSheet";
import {
    Breadcrumb,
    BreadcrumbItem,
    BreadcrumbLink,
    BreadcrumbList,
    BreadcrumbPage,
    BreadcrumbSeparator,
} from "@/components/ui/breadcrumb";

interface MediaFile {
    id: string;
    name: string;
    url: string;
    folder: string;
    size: number;
    created_at: string;
    alt?: string;
    caption?: string;
}

const FOLDERS = ["portfolio", "services", "blogs", "general"];
const BUCKET_NAME = "media";

const AdminMedia = () => {
    const [files, setFiles] = useState<MediaFile[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [isUploading, setIsUploading] = useState(false);
    const [selectedFolder, setSelectedFolder] = useState<string>("all");
    const [selectedType, setSelectedType] = useState<string>("all");
    const [searchQuery, setSearchQuery] = useState("");
    const [viewMode, setViewMode] = useState<"grid" | "list">("grid");
    const [copiedUrl, setCopiedUrl] = useState<string | null>(null);

    const [selectedFiles, setSelectedFiles] = useState<Set<string>>(new Set());
    const [previewFile, setPreviewFile] = useState<MediaFile | null>(null);
    const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
    const [bulkDeleteDialogOpen, setBulkDeleteDialogOpen] = useState(false);
    const [fileToDelete, setFileToDelete] = useState<MediaFile | null>(null);

    const { toast } = useToast();

    useEffect(() => {
        fetchFiles();
    }, []);

    const fetchFiles = async () => {
        setIsLoading(true);
        const allFiles: MediaFile[] = [];

        for (const folder of FOLDERS) {
            const { data, error } = await supabase.storage
                .from(BUCKET_NAME)
                .list(folder, { limit: 100, sortBy: { column: "created_at", order: "desc" } });

            if (data && !error) {
                const folderFiles = data
                    .filter((file) => file.name !== ".emptyFolderPlaceholder")
                    .map((file) => {
                        const { data: { publicUrl } } = supabase.storage
                            .from(BUCKET_NAME)
                            .getPublicUrl(`${folder}/${file.name}`);

                        // Extract metadata
                        const metadata = file.metadata || {};

                        return {
                            id: file.id || `${folder}-${file.name}`,
                            name: file.name,
                            url: publicUrl,
                            folder,
                            size: metadata.size || 0,
                            created_at: file.created_at || new Date().toISOString(),
                            alt: metadata.alt || "",
                            caption: metadata.caption || ""
                        };
                    });
                allFiles.push(...folderFiles);
            }
        }

        setFiles(allFiles);
        setIsLoading(false);
    };

    const [uploadError, setUploadError] = useState<string | null>(null);

    const handleUpload = async (uploadFiles: File[]) => {
        if (!uploadFiles || uploadFiles.length === 0) return;

        setIsUploading(true);
        setUploadError(null);
        const folder = selectedFolder === "all" ? "general" : selectedFolder;

        try {
            const errors: string[] = [];
            let successCount = 0;

            for (const file of uploadFiles) {
                try {
                    const fileExt = file.name.split(".").pop();
                    const fileName = `${Date.now()}-${Math.random().toString(36).substring(2, 8)}.${fileExt}`;
                    const filePath = `${folder}/${fileName}`;

                    const { error } = await supabase.storage
                        .from(BUCKET_NAME)
                        .upload(filePath, file);

                    if (error) throw error;
                    successCount++;
                } catch (err: any) {
                    console.error(`Error uploading ${file.name}:`, err);
                    errors.push(`${file.name}: ${err.message}`);
                }
            }

            if (successCount > 0) {
                toast({ title: `${successCount} file(s) uploaded successfully` });
                fetchFiles();
            }

            if (errors.length > 0) {
                setUploadError(`Failed to upload ${errors.length} file(s). ${errors[0]}`);
                toast({
                    title: "Partially failed",
                    description: "Some files failed to upload. See details above.",
                    variant: "destructive",
                });
            }
        } catch (error: any) {
            setUploadError(error.message);
            toast({
                title: "Upload failed",
                description: error.message,
                variant: "destructive",
            });
        } finally {
            setIsUploading(false);
        }
    };

    const handleSingleDelete = async () => {
        if (!fileToDelete) return;

        const { error } = await supabase.storage
            .from(BUCKET_NAME)
            .remove([`${fileToDelete.folder}/${fileToDelete.name}`]);

        if (error) {
            toast({ title: "Delete failed", description: error.message, variant: "destructive" });
        } else {
            toast({ title: "File deleted" });
            setFiles((prev) => prev.filter((f) => f.id !== fileToDelete.id));
        }
        setFileToDelete(null);
    };

    const handleBulkDelete = async () => {
        const filesToDelete = files.filter(f => selectedFiles.has(f.id));
        const paths = filesToDelete.map(f => `${f.folder}/${f.name}`);

        const { error } = await supabase.storage
            .from(BUCKET_NAME)
            .remove(paths);

        if (error) {
            toast({ title: "Delete failed", description: error.message, variant: "destructive" });
        } else {
            toast({ title: `${filesToDelete.length} files deleted` });
            setFiles((prev) => prev.filter((f) => !selectedFiles.has(f.id)));
            setSelectedFiles(new Set());
        }
    };

    const copyToClipboard = (url: string) => {
        navigator.clipboard.writeText(url);
        setCopiedUrl(url);
        toast({ title: "URL copied to clipboard" });
        setTimeout(() => setCopiedUrl(null), 2000);
    };

    const toggleFileSelection = (fileId: string) => {
        const newSelected = new Set(selectedFiles);
        if (newSelected.has(fileId)) {
            newSelected.delete(fileId);
        } else {
            newSelected.add(fileId);
        }
        setSelectedFiles(newSelected);
    };

    const toggleSelectAll = () => {
        if (selectedFiles.size === filteredFiles.length) {
            setSelectedFiles(new Set());
        } else {
            setSelectedFiles(new Set(filteredFiles.map(f => f.id)));
        }
    };

    const filteredFiles = files.filter((file) => {
        const matchesFolder = selectedFolder === "all" || file.folder === selectedFolder;
        const matchesSearch = file.name.toLowerCase().includes(searchQuery.toLowerCase());

        let matchesType = true;
        if (selectedType === "image") {
            matchesType = /\.(jpg|jpeg|png|gif|webp|svg)$/i.test(file.name);
        } else if (selectedType === "video") {
            matchesType = /\.(mp4|webm|ogg)$/i.test(file.name);
        }

        return matchesFolder && matchesSearch && matchesType;
    });

    const isSelectionMode = selectedFiles.size > 0;

    if (isLoading) {
        return (
            <div className="flex items-center justify-center h-64">
                <Loader2 className="w-8 h-8 animate-spin text-primary" />
            </div>
        );
    }

    return (
        <div className="space-y-6">
            <Breadcrumb>
                <BreadcrumbList>
                    <BreadcrumbItem>
                        <BreadcrumbLink href="/admin">Admin</BreadcrumbLink>
                    </BreadcrumbItem>
                    <BreadcrumbSeparator />
                    <BreadcrumbItem>
                        <BreadcrumbPage>Media Library</BreadcrumbPage>
                    </BreadcrumbItem>
                </BreadcrumbList>
            </Breadcrumb>

            <div className="flex items-center justify-between">
                <div>
                    <h1 className="font-display text-3xl font-bold">Media Library</h1>
                    <p className="text-muted-foreground mt-1">Manage images and files</p>
                </div>
            </div>

            {/* Selection Bar */}
            {isSelectionMode && (
                <motion.div
                    initial={{ opacity: 0, y: -10 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="flex items-center justify-between bg-primary/10 border border-primary/20 rounded-lg px-4 py-3"
                >
                    <div className="flex items-center gap-3">
                        <CheckSquare className="w-5 h-5 text-primary" />
                        <span className="font-medium">{selectedFiles.size} selected</span>
                    </div>
                    <div className="flex items-center gap-2">
                        <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => setSelectedFiles(new Set())}
                        >
                            Clear
                        </Button>
                        <Button
                            variant="destructive"
                            size="sm"
                            onClick={() => setBulkDeleteDialogOpen(true)}
                        >
                            <Trash2 className="w-4 h-4 mr-2" />
                            Delete Selected
                        </Button>
                    </div>
                </motion.div>
            )}

            {/* Filters */}
            <div className="flex flex-wrap items-center gap-4">
                <div className="relative flex-1 min-w-[200px]">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                    <Input
                        placeholder="Search files..."
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        className="pl-10"
                    />
                </div>
                <Select value={selectedFolder} onValueChange={setSelectedFolder}>
                    <SelectTrigger className="w-[150px]">
                        <FolderOpen className="w-4 h-4 mr-2" />
                        <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                        <SelectItem value="all">All Folders</SelectItem>
                        {FOLDERS.map((folder) => (
                            <SelectItem key={folder} value={folder} className="capitalize">
                                {folder}
                            </SelectItem>
                        ))}
                    </SelectContent>
                </Select>
                <Button variant="outline" size="sm" onClick={toggleSelectAll}>
                    {selectedFiles.size === filteredFiles.length && filteredFiles.length > 0 ? (
                        <>
                            <CheckSquare className="w-4 h-4 mr-2" />
                            Deselect All
                        </>
                    ) : (
                        <>
                            <Square className="w-4 h-4 mr-2" />
                            Select All
                        </>
                    )}
                </Button>
                <div className="flex border rounded-md overflow-hidden">
                    <Button
                        variant={viewMode === "grid" ? "secondary" : "ghost"}
                        size="icon"
                        onClick={() => setViewMode("grid")}
                    >
                        <Grid className="w-4 h-4" />
                    </Button>
                    <Button
                        variant={viewMode === "list" ? "secondary" : "ghost"}
                        size="icon"
                        onClick={() => setViewMode("list")}
                    >
                        <List className="w-4 h-4" />
                    </Button>
                </div>
            </div>

            {/* Drop Zone */}
            <MediaUploadZone
                onUpload={handleUpload}
                isUploading={isUploading}
                selectedFolder={selectedFolder}
                errorMessage={uploadError}
            />

            {/* Files Grid/List */}
            <MediaGrid
                files={filteredFiles}
                viewMode={viewMode}
                selectedFiles={selectedFiles}
                onToggleSelection={toggleFileSelection}
                onPreview={setPreviewFile}
                onDelete={(file) => { setFileToDelete(file); setDeleteDialogOpen(true); }}
                onCopyUrl={copyToClipboard}
                copiedUrl={copiedUrl}
            />

            {/* Image Details Sheet */}
            <MediaDetailsSheet
                file={previewFile}
                open={!!previewFile}
                onClose={() => setPreviewFile(null)}
                onDelete={(file) => { setFileToDelete(file); setDeleteDialogOpen(true); }}
                onCopyUrl={copyToClipboard}
            />

            {/* Single Delete Confirmation */}
            <ConfirmDialog
                open={deleteDialogOpen}
                onOpenChange={setDeleteDialogOpen}
                title="Delete File"
                description={`Are you sure you want to delete "${fileToDelete?.name}"? This action cannot be undone.`}
                confirmText="Delete"
                variant="destructive"
                onConfirm={handleSingleDelete}
            />

            {/* Bulk Delete Confirmation */}
            <ConfirmDialog
                open={bulkDeleteDialogOpen}
                onOpenChange={setBulkDeleteDialogOpen}
                title="Delete Selected Files"
                description={`Are you sure you want to delete ${selectedFiles.size} files? This action cannot be undone.`}
                confirmText="Delete All"
                variant="destructive"
                onConfirm={handleBulkDelete}
            />
        </div>
    );
};

export default AdminMedia;

import { useState, useEffect } from "react";
import { motion } from "framer-motion";
import {
  Save,
  Loader2,
  Plus,
  Image,
  Trash2,
} from "lucide-react";
