export default function AdminTestimonials() {
    const [isOpen, setIsOpen] = useState(false);
    const [editingId, setEditingId] = useState<number | null>(null);
    const [formData, setFormData] = useState({
        author_name: "",
        role: "",
        content: "",
        rating: 5,
        is_featured: true,
    });

    const { toast } = useToast();
    const queryClient = useQueryClient();

    // Fetch testimonials
    const { data: testimonials, isLoading } = useQuery({
        queryKey: ["testimonials"],
        queryFn: async () => {
            const { data, error } = await supabase
                .from("testimonials")
                .select("*")
                .order("created_at", { ascending: false });

            if (error) throw error;
            return data;
        },
    });

    // Create/Update mutation
    const mutation = useMutation({
        mutationFn: async (vars: typeof formData & { id?: number }) => {
            if (vars.id) {
                const { error } = await supabase
                    .from("testimonials")
                    .update(vars)
                    .eq("id", vars.id);
                if (error) throw error;
            } else {
                const { error } = await supabase
                    .from("testimonials")
                    .insert([vars]);
                if (error) throw error;
            }
        },
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ["testimonials"] });
            setIsOpen(false);
            resetForm();
            toast({ title: "Success", description: "Testimonial saved successfully." });
        },
        onError: (error) => {
            toast({ variant: "destructive", title: "Error", description: error.message });
        },
    });

    // Delete mutation
    const deleteMutation = useMutation({
        mutationFn: async (id: number) => {
            const { error } = await supabase.from("testimonials").delete().eq("id", id);
            if (error) throw error;
        },
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ["testimonials"] });
            toast({ title: "Deleted", description: "Testimonial removed." });
        },
    });

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        mutation.mutate({ ...formData, id: editingId ?? undefined });
    };

    const handleEdit = (item: any) => {
        setEditingId(item.id);
        setFormData({
            author_name: item.author_name,
            role: item.role,
            content: item.content,
            rating: item.rating,
            is_featured: item.is_featured,
        });
        setIsOpen(true);
    };

    const resetForm = () => {
        setEditingId(null);
        setFormData({ author_name: "", role: "", content: "", rating: 5, is_featured: true });
    };

    return (
        <div className="space-y-6">
            <Breadcrumb>
                <BreadcrumbList>
                    <BreadcrumbItem>
                        <BreadcrumbLink href="/admin">Admin</BreadcrumbLink>
                    </BreadcrumbItem>
                    <BreadcrumbSeparator />
                    <BreadcrumbItem>
                        <BreadcrumbPage>Testimonials</BreadcrumbPage>
                    </BreadcrumbItem>
                </BreadcrumbList>
            </Breadcrumb>

            <div className="flex items-center justify-between">
                <div>
                    <h2 className="text-3xl font-display font-bold text-[hsl(var(--admin-foreground))]">Testimonials</h2>
                    <p className="text-[hsl(var(--admin-muted))]">Manage client reviews and feedback.</p>
                </div>
                <Button onClick={() => { resetForm(); setIsOpen(true); }}>
                    <Plus className="mr-2 h-4 w-4" /> Add Testimonial
                </Button>
            </div>

            <Dialog open={isOpen} onOpenChange={setIsOpen}>
                <DialogContent className="sm:max-w-[500px]">
                    <DialogHeader>
                        <DialogTitle>{editingId ? "Edit Testimonial" : "New Testimonial"}</DialogTitle>
                    </DialogHeader>
                    <form onSubmit={handleSubmit} className="space-y-4">
                        <div className="grid gap-2">
                            <Label htmlFor="author">Author Name</Label>
                            <Input
                                id="author"
                                value={formData.author_name}
                                onChange={(e) => setFormData({ ...formData, author_name: e.target.value })}
                                required
                            />
                        </div>
                        <div className="grid gap-2">
                            <Label htmlFor="role">Role / Project</Label>
                            <Input
                                id="role"
                                value={formData.role}
                                onChange={(e) => setFormData({ ...formData, role: e.target.value })}
                                placeholder="e.g. Homeowner, Villa Renovation"
                            />
                        </div>
                        <div className="grid gap-2">
                            <Label htmlFor="content">Review</Label>
                            <Textarea
                                id="content"
                                value={formData.content}
                                onChange={(e) => setFormData({ ...formData, content: e.target.value })}
                                required
                            />
                        </div>
                        <div className="grid gap-2">
                            <Label htmlFor="rating">Rating (1-5)</Label>
                            <Input
                                id="rating"
                                type="number"
                                min="1"
                                max="5"
                                value={formData.rating}
                                onChange={(e) => setFormData({ ...formData, rating: parseInt(e.target.value) })}
                                required
                            />
                        </div>
                        <DialogFooter>
                            <Button type="button" variant="outline" onClick={() => setIsOpen(false)}>Cancel</Button>
                            <Button type="submit" disabled={mutation.isPending}>
                                {mutation.isPending ? "Saving..." : "Save Testimonial"}
                            </Button>
                        </DialogFooter>
                    </form>
                </DialogContent>
            </Dialog>

            {isLoading ? (
                <div className="flex items-center justify-center p-8">
                    <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
                </div>
            ) : !testimonials || testimonials.length === 0 ? (
                <EmptyState
                    icon={MessageSquare}
                    title="No testimonials yet"
                    description="Start building trust by adding client testimonials and reviews"
                    primaryAction={{
                        label: "Add Testimonial",
                        onClick: () => { resetForm(); setIsOpen(true); },
                        icon: Plus
                    }}
                />
            ) : (
                <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
                    {testimonials?.map((item: any) => (
                        <Card key={item.id} className="relative group overflow-hidden border-[hsl(var(--admin-border))]">
                            <CardHeader className="pb-3">
                                <div className="flex justify-between items-start">
                                    <div>
                                        <CardTitle className="text-lg">{item.author_name}</CardTitle>
                                        <CardDescription>{item.role}</CardDescription>
                                    </div>
                                    <div className="flex bg-yellow-50 px-2 py-1 rounded text-yellow-600">
                                        <Star className="w-3 h-3 fill-current mr-1 self-center" />
                                        <span className="text-xs font-bold">{item.rating}</span>
                                    </div>
                                </div>
                            </CardHeader>
                            <CardContent>
                                <p className="text-sm text-[hsl(var(--admin-muted))] line-clamp-3">"{item.content}"</p>
                                <div className="absolute top-4 right-4 opacity-0 group-hover:opacity-100 transition-opacity flex gap-2">
                                    <Button variant="outline" size="icon" className="h-8 w-8 bg-white" onClick={() => handleEdit(item)}>
                                        <Edit className="h-4 w-4" />
                                    </Button>
                                    <Button variant="destructive" size="icon" className="h-8 w-8" onClick={() => deleteMutation.mutate(item.id)}>
                                        <Trash2 className="h-4 w-4" />
                                    </Button>
                                </div>
                            </CardContent>
                        </Card>
                    ))}
                </div>
            )}
        </div>
    );
}

import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from "@/components/ui/table";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Search, Mail, Shield, UserPlus, Loader2, Users } from "lucide-react";
import { format } from "date-fns";
import { EmptyState } from "@/components/admin/EmptyState";
import {
    Breadcrumb,
    BreadcrumbItem,
    BreadcrumbLink,
    BreadcrumbList,
    BreadcrumbPage,
    BreadcrumbSeparator,
} from "@/components/ui/breadcrumb";
import { InviteUserDialog } from "@/components/admin/users/InviteUserDialog";
import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuItem,
    DropdownMenuLabel,
    DropdownMenuSeparator,
    DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
    AlertDialog,
    AlertDialogAction,
    AlertDialogCancel,
    AlertDialogContent,
    AlertDialogDescription,
    AlertDialogFooter,
    AlertDialogHeader,
    AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { MoreHorizontal, Trash2, Ban, CheckCircle } from "lucide-react";
import { useToast } from "@/hooks/use-toast";

export default function AdminUsers() {
    const [search, setSearch] = useState("");
    const [inviteOpen, setInviteOpen] = useState(false);
    const [actionUser, setActionUser] = useState<{ id: string, name: string, action: 'suspend' | 'unsuspend' | 'delete' } | null>(null);
    const [actionLoading, setActionLoading] = useState(false);
    const { toast } = useToast();

    const { data: users = [], isLoading, refetch } = useQuery({
        queryKey: ["admin-users"],
        queryFn: async () => {
            const { data, error } = await supabase.rpc("get_admin_users");
            if (error) throw error;
            return data;
        },
    });

    const filteredUsers = users.filter((user: any) =>
        user.email?.toLowerCase().includes(search.toLowerCase()) ||
        user.full_name?.toLowerCase().includes(search.toLowerCase())
    );

    const handleAction = async () => {
        if (!actionUser) return;
        setActionLoading(true);
        try {
            const { data, error } = await supabase.functions.invoke('manage-user', {
                body: { action: actionUser.action, userId: actionUser.id }
            });

            if (error) throw error;
            if (data?.error) throw new Error(data.error);

            toast({
                title: "Success",
                description: `User ${actionUser.action}ed successfully.`
            });
            refetch();
        } catch (error: any) {
            toast({
                title: "Error",
                description: error.message || "Failed to perform action",
                variant: "destructive"
            });
        } finally {
            setActionLoading(false);
            setActionUser(null);
        }
    };

    return (
        <div className="space-y-6">
            <Breadcrumb>
                <BreadcrumbList>
                    <BreadcrumbItem>
                        <BreadcrumbLink href="/admin">Admin</BreadcrumbLink>
                    </BreadcrumbItem>
                    <BreadcrumbSeparator />
                    <BreadcrumbItem>
                        <BreadcrumbPage>Users</BreadcrumbPage>
                    </BreadcrumbItem>
                </BreadcrumbList>
            </Breadcrumb>

            <div className="flex items-center justify-between">
                <div>
                    <h2 className="text-3xl font-display font-bold text-[hsl(var(--admin-foreground))]">Users</h2>
                    <p className="text-[hsl(var(--admin-muted))]">Manage team access and permissions.</p>
                </div>
                <Button onClick={() => setInviteOpen(true)}>
                    <UserPlus className="mr-2 h-4 w-4" /> Invite User
                </Button>
            </div>

            <div className="flex items-center space-x-2">
                <div className="relative flex-1 max-w-sm">
                    <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-muted-foreground" />
                    <Input
                        placeholder="Search users..."
                        className="pl-9"
                        value={search}
                        onChange={(e) => setSearch(e.target.value)}
                    />
                </div>
            </div>

            {isLoading ? (
                <div className="flex justify-center items-center h-64">
                    <Loader2 className="h-8 w-8 animate-spin text-primary" />
                </div>
            ) : filteredUsers.length === 0 ? (
                <EmptyState
                    icon={Users}
                    title="No users found"
                    description={search ? "Try adjusting your search criteria" : "Invite team members to collaborate on your projects"}
                    primaryAction={{
                        label: "Invite User",
                        onClick: () => setInviteOpen(true),
                        icon: UserPlus
                    }}
                />
            ) : (
                <div className="border rounded-md bg-white">
                    <Table>
                        <TableHeader>
                            <TableRow>
                                <TableHead>User</TableHead>
                                <TableHead>Role</TableHead>
                                <TableHead>Status</TableHead>
                                <TableHead>Joined</TableHead>
                                <TableHead className="text-right">Actions</TableHead>
                            </TableRow>
                        </TableHeader>
                        <TableBody>
                            {filteredUsers.map((user: any) => (
                                <TableRow key={user.id}>
                                    <TableCell>
                                        <div className="flex items-center gap-3">
                                            <Avatar>
                                                <AvatarImage src={user.avatar_url} />
                                                <AvatarFallback className="bg-primary/10 text-primary">
                                                    {(user.full_name || user.email || "U").substring(0, 2).toUpperCase()}
                                                </AvatarFallback>
                                            </Avatar>
                                            <div className="flex flex-col">
                                                <span className="font-medium">{user.full_name || "Unknown"}</span>
                                                <div className="flex items-center text-xs text-muted-foreground">
                                                    <Mail className="mr-1 h-3 w-3" />
                                                    {user.email || "N/A"}
                                                </div>
                                            </div>
                                        </div>
                                    </TableCell>
                                    <TableCell>
                                        <div className="flex items-center gap-2">
                                            <Shield className="h-4 w-4 text-primary" />
                                            <span className="capitalize">{user.role || "Viewer"}</span>
                                        </div>
                                    </TableCell>
                                    <TableCell>
                                        <Badge
                                            variant={user.status === 'suspended' ? 'destructive' : 'secondary'}
                                            className={user.status === 'active' ? "bg-green-100 text-green-700 hover:bg-green-100" : ""}
                                        >
                                            {user.status === 'suspended' ? 'Suspended' : 'Active'}
                                        </Badge>
                                    </TableCell>
                                    <TableCell>
                                        {user.created_at ? format(new Date(user.created_at), "MMM d, yyyy") : "N/A"}
                                    </TableCell>
                                    <TableCell className="text-right">
                                        <DropdownMenu>
                                            <DropdownMenuTrigger asChild>
                                                <Button variant="ghost" className="h-8 w-8 p-0">
                                                    <span className="sr-only">Open menu</span>
                                                    <MoreHorizontal className="h-4 w-4" />
                                                </Button>
                                            </DropdownMenuTrigger>
                                            <DropdownMenuContent align="end">
                                                <DropdownMenuLabel>Actions</DropdownMenuLabel>
                                                <DropdownMenuItem onClick={() => navigator.clipboard.writeText(user.id)}>
                                                    Copy ID
                                                </DropdownMenuItem>
                                                <DropdownMenuSeparator />
                                                {user.status === 'suspended' ? (
                                                    <DropdownMenuItem
                                                        className="text-green-600"
                                                        onClick={() => setActionUser({ id: user.id, name: user.full_name || user.email, action: 'unsuspend' })}
                                                    >
                                                        <CheckCircle className="mr-2 h-4 w-4" /> Unsuspend
                                                    </DropdownMenuItem>
                                                ) : (
                                                    <DropdownMenuItem
                                                        className="text-orange-600"
                                                        onClick={() => setActionUser({ id: user.id, name: user.full_name || user.email, action: 'suspend' })}
                                                    >
                                                        <Ban className="mr-2 h-4 w-4" /> Suspend
                                                    </DropdownMenuItem>
                                                )}
                                                <DropdownMenuItem
                                                    className="text-red-600 focus:text-red-600"
                                                    onClick={() => setActionUser({ id: user.id, name: user.full_name || user.email, action: 'delete' })}
                                                >
                                                    <Trash2 className="mr-2 h-4 w-4" /> Delete
                                                </DropdownMenuItem>
                                            </DropdownMenuContent>
                                        </DropdownMenu>
                                    </TableCell>
                                </TableRow>
                            ))}
                        </TableBody>
                    </Table>
                </div>
            )}

            <InviteUserDialog
                open={inviteOpen}
                onOpenChange={setInviteOpen}
                onSuccess={() => refetch()}
            />

            <AlertDialog open={!!actionUser} onOpenChange={(open) => !open && setActionUser(null)}>
                <AlertDialogContent>
                    <AlertDialogHeader>
                        <AlertDialogTitle>Are you sure?</AlertDialogTitle>
                        <AlertDialogDescription>
                            This will {actionUser?.action} <b>{actionUser?.name}</b>.
                            {actionUser?.action === 'delete' && " This action cannot be undone."}
                            {actionUser?.action === 'suspend' && " They will be unable to log in until unsuspended."}
                        </AlertDialogDescription>
                    </AlertDialogHeader>
                    <AlertDialogFooter>
                        <AlertDialogCancel disabled={actionLoading}>Cancel</AlertDialogCancel>
                        <AlertDialogAction
                            onClick={(e) => { e.preventDefault(); handleAction(); }}
                            disabled={actionLoading}
                            className={actionUser?.action === 'delete' || actionUser?.action === 'suspend' ? "bg-destructive text-destructive-foreground hover:bg-destructive/90" : ""}
                        >
                            {actionLoading ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : null}
                            Confirm {actionUser?.action}
                        </AlertDialogAction>
                    </AlertDialogFooter>
                </AlertDialogContent>
            </AlertDialog>
        </div>
    );
}
